import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.O93z6AWZ.js";const m=JSON.parse('{"title":"Machine Learning in Healthcare — English","description":"","frontmatter":{"layout":"home","title":"Machine Learning in Healthcare — English","hero":{"name":"Machine Learning in Healthcare & Clinical Care","text":"English Edition","actions":[{"theme":"brand","text":"🚀 Start Reading — Chapter 1","link":"/en/ch01"},{"theme":"alt","text":"📋 Detailed Syllabus (CLO/PLO)","link":"/en/syllabus"}]},"features":[{"icon":"🎯","title":"16-Item Standard Pedagogical Framework v5","details":"Every chapter is comprehensively designed — from Bloom-aligned Course Learning Outcomes (CLO), clinical insight boxes, medical safety warning boxes, to 40 multiple-choice & essay review questions."},{"icon":"🔬","title":"8 Real Clinical Case Studies","details":"From ECG arrhythmia diagnosis (MIT-BIH) and EHR preprocessing (MIMIC-IV), to decoding p >> n gene microarrays and classifying chest X-ray lesions with Grad-CAM."},{"icon":"🔒","title":"Closed-Loop BibTeX Citation Discipline","details":"Over 320 closed-loop academic citations drawing on 58 international references (Bishop, Hastie, Géron, MIT Critical Data, Nature Medicine, Lancet Digital Health)."},{"icon":"💻","title":"Independent Hands-on Code Lab Library","details":"8 Python code labs, each 100% tested, integrating patient-level data-leakage control and medical error-cost evaluation."}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),s={name:"en/index.md"};function r(o,a,l,c,p,d){return t(),i("div",null,[...a[0]||(a[0]=[n('<h2 id="📚-all-8-chapters-—-now-fully-available-in-english" tabindex="-1">📚 All 8 Chapters — Now Fully Available in English <a class="header-anchor" href="#📚-all-8-chapters-—-now-fully-available-in-english" aria-label="Permalink to &quot;📚 All 8 Chapters — Now Fully Available in English&quot;">​</a></h2><div class="chapter-grid"><a href="/hmyt-book/en/ch01" class="chapter-card"><div><span class="badge-archetype badge-a">Archetype A</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 01</span></div><h3>Chapter 1: Introduction to ML in Healthcare</h3><p>Overview of the medical AI ecosystem, the 4Vs challenge of digitized biomedical data, the standard workflow from research to clinical deployment, and the legal framework.</p><div class="meta"><span>🩺 ECG, EHR &amp; Clinical Classification</span></div></a><a href="/hmyt-book/en/ch02" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 02</span></div><h3>Chapter 2: Medical Data Exploration &amp; Preprocessing</h3><p>EHR tabular data-cleaning strategy, handling missing data (MCAR/MAR/MNAR), feature scaling, and encoding medical laboratory data.</p><div class="meta"><span>🔬 KNNImputer &amp; RobustScaler</span></div></a><a href="/hmyt-book/en/ch03" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 03</span></div><h3>Chapter 3: Linear Models, Regression &amp; Odds Ratio</h3><p>Linear regression, logistic regression, quantitative medical interpretation via the Odds Ratio (OR), and clinical risk analysis.</p><div class="meta"><span>📊 Odds Ratio &amp; Logistic Regression</span></div></a><a href="/hmyt-book/en/ch04" class="chapter-card"><div><span class="badge-archetype badge-d">Archetype D</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 04</span></div><h3>Chapter 4: Regularization, Validation &amp; Model Evaluation</h3><p>L1/L2 techniques (Lasso/Ridge/ElasticNet) on p &gt;&gt; n data, medical confusion matrices (Sensitivity/Specificity), ROC-AUC and Precision-Recall curves.</p><div class="meta"><span>🎯 Nested CV &amp; Medical ROC-AUC</span></div></a><a href="/hmyt-book/en/ch05" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 05</span></div><h3>Chapter 5: Nonlinear Models, SVM &amp; Feature Selection</h3><p>Support Vector Machines (SVM), the Kernel Trick, decision trees, and Recursive Feature Elimination (RFE) in cancer diagnosis.</p><div class="meta"><span>🧬 Kernel SVM &amp; RFE Feature Selection</span></div></a><a href="/hmyt-book/en/ch06" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 06</span></div><h3>Chapter 6: Unsupervised Learning &amp; Dimensionality Reduction</h3><p>Clinical phenotype clustering (K-Means, GMM), dimensionality reduction via PCA/t-SNE/UMAP, and blind biosignal source separation with FastICA.</p><div class="meta"><span>📉 PCA, UMAP &amp; FastICA Signal Separation</span></div></a><a href="/hmyt-book/en/ch07" class="chapter-card"><div><span class="badge-archetype badge-d">Archetype D</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 07</span></div><h3>Chapter 7: Artificial Neural Networks: Optimization &amp; Hyperparameter Tuning</h3><p>Multilayer Perceptron (MLP) architecture, the backpropagation algorithm, activation functions (ReLU/GELU), and the anti-overfitting strategies Dropout and Batch Normalization.</p><div class="meta"><span>🧠 Deep MLP &amp; Adam Optimization</span></div></a><a href="/hmyt-book/en/ch08" class="chapter-card"><div><span class="badge-archetype badge-e">Archetype E</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chapter 08</span></div><h3>Chapter 8: Convolutional Neural Networks (CNN) in Medical Imaging</h3><p>2D/3D convolutional blocks, classic architectures ResNet/DenseNet, Transfer Learning, and explaining medical-image AI decisions via Grad-CAM.</p><div class="meta"><span>🩻 ResNet, Transfer Learning &amp; Grad-CAM</span></div></a></div><h2 id="course-management-pages" tabindex="-1">Course Management Pages <a class="header-anchor" href="#course-management-pages" aria-label="Permalink to &quot;Course Management Pages&quot;">​</a></h2><ul><li><strong><a href="/hmyt-book/en/course_project">Course Project Bank</a></strong> — the full topic matrix (15 topics across 4 groups), management framework, and grading rubric.</li><li><strong><a href="/hmyt-book/en/submit">Submit Assignment</a></strong> — how to submit your project to the shared class repository via Pull Request.</li></ul><p>Individual topic detail pages (literature review, workflow, timeline) are translated progressively — the topic matrix marks which ones already have an English version; untranslated topics link to the Vietnamese page.</p><p>👉 <strong><a href="/hmyt-book/">Go to the Vietnamese homepage</a></strong> for the original-language edition.</p>',6)])])}const g=e(s,[["render",r]]);export{m as __pageData,g as default};
